import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Automation","description":"Run AzureScout unattended from Azure Automation, GitHub Actions, or Azure DevOps.","frontmatter":{"description":"Run AzureScout unattended from Azure Automation, GitHub Actions, or Azure DevOps."},"headers":[],"relativePath":"automation-guide/index.md","filePath":"automation-guide/index.md"}'),i={name:"automation-guide/index.md"};function r(d,e,s,u,l,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h1><p>AzureScout is built to run without a human at the keyboard: no interactive prompts, no COM dependencies, and a run log written for every run including failed ones.</p><h2 id="pick-a-host" tabindex="-1">Pick a host <a class="header-anchor" href="#pick-a-host" aria-label="Permalink to &quot;Pick a host&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use it when</th></tr></thead><tbody><tr><td><a href="./automation.html">Azure Automation Account</a></td><td>You want a scheduled runbook inside Azure, authenticating with a managed identity and writing to blob storage</td></tr><tr><td><a href="./github-actions.html">GitHub Actions</a></td><td>Your pipelines already live in GitHub — a composite action is provided</td></tr><tr><td><a href="./azure-devops.html">Azure DevOps</a></td><td>Your pipelines live in ADO, or you also want to inventory ADO itself: projects, pipelines, service connections, repos and agent pools</td></tr></tbody></table><h2 id="what-every-unattended-run-needs" tabindex="-1">What every unattended run needs <a class="header-anchor" href="#what-every-unattended-run-needs" aria-label="Permalink to &quot;What every unattended run needs&quot;">​</a></h2><ul><li><strong>A non-interactive identity</strong> — a managed identity, or a service principal with a secret or certificate. See <a href="./../guide/authentication.html">Authentication</a>.</li><li><strong>Reader at the scope you want covered.</strong> Anything narrower silently reduces what is collected, so run <a href="./../guide/permissions.html"><code>-PermissionAudit</code></a> once from the same identity first.</li><li><strong>Somewhere durable for the output.</strong> In an Azure Automation sandbox the filesystem is discarded when the job ends, so blob storage is the only copy that survives.</li></ul><h2 id="reading-a-headless-run" tabindex="-1">Reading a headless run <a class="header-anchor" href="#reading-a-headless-run" aria-label="Permalink to &quot;Reading a headless run&quot;">​</a></h2><p>Every run writes <code>scout-run.log</code> with phases, elapsed times, counts and full error detail — including runs that failed. Two further artefacts make a run auditable rather than merely finished:</p><ul><li><code>raw-inventory.json</code> — everything collected, written <strong>before</strong> any manifest decided what to display, so a resource type no collector claims still leaves a trace.</li><li><code>collector-rowcounts.json</code> — what each collector produced, and why it produced nothing.</li></ul><p>That last distinction is the one that matters unattended: an empty worksheet and a collector that was never permitted to run look identical in a report, and these files tell them apart.</p>',10)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
